import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        // bound minSum to reasonable range to allow Collect to proceed
        minSum = bound(minSum, 1, type(uint256).max / 2);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // Setup: initialize contract and set MinSum
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Record initial contract balance
        uint256 initialContractBalance = address(c).balance;

        // Deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Collect
        uint256 contractBalanceBeforeCollect = address(c).balance;
        vm.prank(actor);
        bool collectSuccess = false;
        try c.Collect(collectAmount) { collectSuccess = true; } catch { collectSuccess = false; }
        uint256 contractBalanceAfterCollect = address(c).balance;

        if (collectSuccess && contractBalanceBeforeCollect >= collectAmount) {
            // After a successful collect, contract balance should decrease by exactly collectAmount (no Ether creation from thin air)
            assertTrue(contractBalanceBeforeCollect - collectAmount == contractBalanceAfterCollect);
        } else {
            // If collect fails, contract balance should remain unchanged
            assertTrue(contractBalanceBeforeCollect == contractBalanceAfterCollect);
        }
    }
}

