pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Keep caller non-zero to ensure reasonable external actor
        vm.assume(caller != address(0));
        // Keep depositAmount > 0 so that the subtraction effect happens
        vm.assume(depositAmount > 0);
        // Ensure no overflow in the require check of Deposit (note: the buggy contract still uses the safe check "balances + msg.value >= balances" before the subtraction)
        vm.assume(depositAmount <= type(uint256).max - 1);
        // Ensure collectAmount is at least MinSum so Collect can proceed if balance condition holds
        vm.assume(collectAmount > 0);

        // Initialize the contract: set up MinSum and LogFile, then call Initialized
        c.SetMinSum(0);
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();

        // Give caller some ether for deposit
        vm.deal(caller, depositAmount);

        // Record balance of caller before Deposit
        uint256 balBeforeDeposit = c.balances(caller);

        // Caller deposits
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Now record balance before Collect
        uint256 balBeforeCollect = c.balances(caller);

        // If balance after deposit is at least collectAmount and MinSum (which is 0), attempt Collect.
        // But in buggy version balance may underflow, so we only attempt if balance >= collectAmount.
        // In reference version, this guard ensures Collect succeeds when condition holds.
        if (balBeforeCollect >= collectAmount) {
            vm.prank(caller);
            bool ok;
            try c.Collect(collectAmount) {
                ok = true;
            } catch {
                ok = false;
            }

            uint256 balAfterCollect = c.balances(caller);

            // Reference property: after a successful Collect, the caller's balance never exceeds their pre-collect balance.
            // (It should decrease by exactly collectAmount in the reference, but non-increase is a universal property.)
            // Bug: In the buggy version, Deposit subtracted instead of added, making balance huge (underflow),
            // so after Collect subtracts collectAmount, the resulting balance can be larger than the pre-collect balance
            // because underflow created an enormous balance.
            if (ok) {
                assertTrue(balAfterCollect <= balBeforeCollect);
            } else {
                // In reference, if revert happens, the balance remains unchanged; we could assert that,
                // but the main property is already captured above. To avoid vacuously true assertion for all inputs,
                // we assert true always but the real differentiator is the successful case.
                assertTrue(true);
            }
        } else {
            // If balance insufficient, Collect won't do anything in either version; skip.
            assertTrue(true);
        }
    }
}

