import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(minSum > 0 && minSum < type(uint256).max / 2);
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount > 0 && collectAmount < type(uint256).max / 2);
        vm.assume(depositAmount >= minSum);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(this));
        c.Initialized();

        // Perform a deposit from a random address
        address depositor = address(uint160(uint256(keccak256(abi.encode(depositAmount)))));
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Perform a collect from the same address
        vm.prank(depositor);
        c.Collect(collectAmount);

        // Calculate the sum of all balances. We know the only non-zero balance is the depositor's.
        // To prove the general rule, we iterate through all addresses? Not possible.
        // Instead, we rely on the invariant: totalEther = sum of all balances.
        // After deposit and collect, totalEther = depositAmount - collectAmount.
        // Sum of balances = balances[depositor] (should be depositAmount - collectAmount) + balances[address(0)] (0 in reference, non-zero in mutant).
        // The invariant holds if balances[depositor] + balances[address(0)] == address(c).balance.
        // In reference: balances[address(0)] = 0, so invariant holds.
        // In mutant: balances[address(0)] = depositAmount, so invariant breaks.
        uint256 totalBalance = c.balances(depositor) + c.balances(address(0));
        assertTrue(totalBalance == address(c).balance);
    }
}

