        c.Deposit{value: val2}();
        uint256 balAfterSecond = c.balances(sender);

        // General rule: the second balance increment should be proportional to val2/val1 of the first increment.
        // Since balAfterFirst = increment1 (starting from 0) and balAfterSecond = increment1 + increment2,
        // we assert: increment1 * val2 == increment2 * val1, which is: balAfterFirst * val2 == (balAfterSecond - balAfterFirst) * val1.
        // This holds for the reference (increment = msg.value) but fails for the buggy version (increment = 1).
        uint256 diff = balAfterSecond - balAfterFirst;
        assertTrue(balAfterFirst * val2 == diff * val1);
    }
}

