import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(actor != address(this));

        // initialize contract for use
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // actor deposits 'amount' wei
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // actor collects exactly 'amount' wei
        bool collectSucceeded;
        vm.prank(actor);
        try c.Collect(amount) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // property: if collect succeeded, final balance must be >= 0 (trivially true via uint), but more importantly
        // the collect must succeed because the actor deposited exactly the amount they are collecting.
        // The bug makes the deposit credit only 1 wei, so Collect will revert when amount > 1.
        // Thus, the reference C satisfies: collectSucceeded == true for all valid inputs;
        // the buggy version breaks it (collectSucceeded == false) when amount > 1.
        assertTrue(collectSucceeded);
    }
}

